// Every name a reader might type for a kind of tree, for SEARCH ONLY
// (Hidde, 2026-10-31: "when adding a tree I often dont know the english name
// - some people might even prefer latin names"). Generated by
// scripts/species_names.py from our own translations and Wikidata.
//
// The same split as citySearchNames(): the common name a species publishes
// under stays the city file's (hard rule 9), and these names only ever answer
// a search. One file feeds both surfaces, the app through /api/species.json
// and the website through /search-index.json, so "Zomereik" finds the
// Pedunculate Oak on both or on neither.
import fs from "node:fs";
import path from "node:path";
import { DATA } from "./data-dir";

/** One row: our common name, the Latin, every other name flattened.
 * `m: false` is a species we have met in a lead and not mapped yet; `g` a
 * genus, which a chooser offers as "Oak (Quercus sp.)". */
export interface SpeciesNameRow {
  c: string;
  l: string;
  a: string[];
  m?: false;
  g?: true;
}

interface Entry {
  common: string;
  latin: string;
  mapped?: boolean;
  genus?: boolean;
  names?: Record<string, string[]>;
}

let cached: SpeciesNameRow[] | null = null;

export function speciesNameRows(): SpeciesNameRow[] {
  if (cached) return cached;
  const f = path.join(DATA, "species-names.json");
  if (!fs.existsSync(f)) return (cached = []);
  const data = JSON.parse(fs.readFileSync(f, "utf-8"));
  const row = (e: Entry): SpeciesNameRow => {
    const seen = new Set<string>();
    const a: string[] = [];
    for (const list of Object.values(e.names ?? {})) {
      for (const n of list) {
        const k = n.toLowerCase();
        if (!seen.has(k)) { seen.add(k); a.push(n); }
      }
    }
    return {
      c: e.common, l: e.latin, a,
      ...(e.mapped === false ? { m: false as const } : {}),
      ...(e.genus ? { g: true as const } : {}),
    };
  };
  cached = [...(data.species ?? []), ...(data.genera ?? [])].map(row);
  return cached;
}

/** Common name -> the other names of a species we map. */
export function speciesSearchNames(): Map<string, string[]> {
  const out = new Map<string, string[]>();
  for (const r of speciesNameRows()) {
    if (r.m === false || r.g) continue;
    out.set(r.c, r.a);
  }
  return out;
}
